from test_directed_thanks import test,solo
manual=solo+"local B=BuffTap; B.db.manualThanks=true; B.db.helperThanksResting=true; B:Commit(nil,'test'); UnitNameFromGUID=function() return 'Giver','Surname' end; local sent={}; SendChatMessage=function(...) sent[#sent+1]={...} end; local a={casterGUID='Player-Driveby',spellId=1459,name='Arcane Intellect'}; "
test('Manual thanks defaults off',solo+"assert(BuffTap.db.manualThanks==false)")
test('Manual thanks offers immediately and sends once',manual+"B:OfferManualThanks(a); local e=B.manualThanksQueue[a.casterGUID]; assert(e and B.manualThanksButton:IsShown()); assert(B:SendManualThanks(e)); assert(#sent==1 and sent[1][1]=='Thank you for Arcane Intellect!' and sent[1][2]=='WHISPER' and sent[1][4]=='Giver Surname'); assert(not B:SendManualThanks(e) and #sent==1)")
test('Manual thanks merges received buffs',manual+"B:OfferManualThanks(a); a.spellId=1243; a.name='Fortitude'; B:OfferManualThanks(a); local e=B.manualThanksQueue[a.casterGUID]; assert(B:ManualThanksText(e)=='Thank you for Arcane Intellect, Fortitude!')")
test('Manual thanks refuses changed identity',manual+"B:OfferManualThanks(a); local e=B.manualThanksQueue[a.casterGUID]; UnitNameFromGUID=function() return 'Other','Person' end; assert(not B:SendManualThanks(e) and #sent==0)")
test('Manual thanks needs readable full name',manual+"UnitNameFromGUID=function() return 'Giver','' end; B:OfferManualThanks(a); assert(not next(B.manualThanksQueue or {}))")
for pause in ['true','false']:
 test('Manual resting rule with global pause '+pause,manual+"B:OfferManualThanks(a); local e=B.manualThanksQueue[a.casterGUID]; B.db.helperThanksResting=false; B.db.pauseResting="+pause+"; IsResting=function() return true end; assert(not B:SendManualThanks(e)); B:UpdateManualThanks(); assert(not next(B.manualThanksQueue) and not B.manualThanksButton:IsShown() and #sent==0)")
test('Manual thanks allows resting opt in',manual+"B.db.pauseResting=true; IsResting=function() return true end; B:OfferManualThanks(a); assert(B:SendManualThanks(B.manualThanksQueue[a.casterGUID]) and #sent==1)")
test('Real buff action takes priority over manual thanks',manual+"B:OfferManualThanks(a); local e=B.manualThanksQueue[a.casterGUID]; B.action={id=5232}; B:UpdateManualThanks(); assert(not B.manualThanksButton:IsShown() and not B:SendManualThanks(e) and #sent==0)")
test('Manual expiry is bounded',manual+"B:OfferManualThanks(a); now=now+15; B:UpdateManualThanks(); assert(not next(B.manualThanksQueue) and not B.manualThanksButton:IsShown())")
test('Right click dismiss survives automatic retry',manual+"B:OfferManualThanks(a); B.manualThanksButton.scripts.OnClick(nil,'RightButton'); B:OfferManualThanks(a); assert(not next(B.manualThanksQueue) and #sent==0)")
test('Manual wins cancels automatic pending and queued thanks',manual+"B:OfferManualThanks(a); B.helperThankPending={x={guid=a.casterGUID}}; B.helperThankQueue={{guid=a.casterGUID}}; assert(B:SendManualThanks(B.manualThanksQueue[a.casterGUID])); assert(not next(B.helperThankPending) and #B.helperThankQueue==0)")
test('Message reset and literal substitution',manual+"assert(B:SetManualThanksMessage('Cheers for [buff]!')); B:OfferManualThanks(a); assert(B:ManualThanksText(B.manualThanksQueue[a.casterGUID])=='Cheers for Arcane Intellect!'); B:SetManualThanksMessage(''); assert(B:ManualThanksTemplate()=='Thank you for %s!')")
test('Manual controls fit existing Helpers card',manual+"B:Options(); assert(B.helperWindow.manualThanks and B.helperWindow.thankMessage and B.helperWindow.thankMessageReset)")

test('Actual unresolved aura offers manual before retry timeout',manual+"C_UnitAuras.GetAuraCasterGUID=function() return a.casterGUID end; auras.player={{spellId=1459,auraInstanceID=88,name='Arcane Intellect'}}; B:InvalidateAura('player'); B:ObserveSoloThanks(); assert(B.manualThanksQueue[a.casterGUID] and next(B.helperThankPending) and #sent==0)")
test('Automatic thanks removes manual fallback',manual+"B:OfferManualThanks(a); local oldG=UnitGUID; UnitGUID=function(u) return u=='target' and a.casterGUID or oldG(u) end; received(1459,'target'); assert(#emotes==1 and not B.manualThanksQueue[a.casterGUID] and #sent==0)")

test('Dismiss affects only selected giver and advances manual queue',manual+"B:OfferManualThanks(a); local first=B.manualThanksQueue[a.casterGUID]; now=now+1; UnitNameFromGUID=function(g) if g==a.casterGUID then return 'Giver','Surname' end return 'Second','Person' end; local other={casterGUID='Player-Second',spellId=1243,name='Fortitude'}; B:OfferManualThanks(other); local second=B.manualThanksQueue[other.casterGUID]; local pending={one={guid=a.casterGUID},two={guid=other.casterGUID}}; local automatic={{guid=a.casterGUID},{guid=other.casterGUID}}; B.helperThankPending=pending; B.helperThankQueue=automatic; local cooldown=B.helperThankCooldowns; assert(B.manualThanksButton.entry==first); B.manualThanksButton.scripts.OnClick(nil,'RightButton'); assert(not B.manualThanksQueue[a.casterGUID] and B.manualThanksQueue[other.casterGUID]==second); assert(B.manualThanksButton:IsShown() and B.manualThanksButton.entry==second); assert(B.helperThankPending==pending and pending.one and pending.two and B.helperThankQueue==automatic and #automatic==2 and B.helperThankCooldowns==cooldown); assert(not B.manualThanksDismissed[other.casterGUID]); assert(B:SendManualThanks(second) and #sent==1 and sent[1][4]=='Second Person')")

test('Percent s replaces literally and preserves legacy messages',manual+"B:SetManualThanksMessage('Thanks for %s / %s'); a.name='A %s buff'; B:OfferManualThanks(a); local e=B.manualThanksQueue[a.casterGUID]; assert(B:ManualThanksText(e)=='Thanks for A %s buff / A %s buff'); B:SetManualThanksMessage('Cheers for [buff]'); assert(B:ManualThanksText(e)=='Cheers for A %s buff'); B.db.thankMessage='Thank you for [buff]!'; assert(B:ManualThanksTemplate()=='Thank you for %s!')")
